using System;
using UnityEngine;
using UnityEngine.UI;

namespace RollerSort {
 public sealed partial class RollerGame {
  LifeClock life;bool journey,failed,spaceOffer;Text lifeCounter,refillCountdown;float nextLifeRefresh;
  long Now=>DateTimeOffset.UtcNow.ToUnixTimeSeconds();
  void LoadLives(){long.TryParse(PlayerPrefs.GetString("lifeNext","0"),out long next);life=new LifeClock(PlayerPrefs.GetInt("lives",5),next);life.Refresh(Now);SaveLives();}
  void SaveLives(){if(diagnosticsActive)return;PlayerPrefs.SetInt("lives",life.Count);PlayerPrefs.SetString("lifeNext",life.Next.ToString());PlayerPrefs.Save();}
  string LifeTime(){long sec=life.Remaining(Now);return life.Count==5?GameLanguage.Text("Max"):$"{sec/60:00}:{sec%60:00}";}
  void LifeTick(){if(life==null||Time.unscaledTime<nextLifeRefresh)return;nextLifeRefresh=Time.unscaledTime+1;int before=life.Count;life.Refresh(Now);if(before!=life.Count)SaveLives();if(lifeCounter)lifeCounter.text=life.Count+"  "+LifeTime();if(refillCountdown)refillCountdown.text=GameLanguage.Text("Yeni can: "+LifeTime()+"\nCanlar 30 dakikada bir yenilenir.");}
  void LifeHud(Transform parent){var h=Picture(parent,"hud",new Vector2(-16,107),new Vector2(141,43));Picture(h,"heart",new Vector2(-49,21),new Vector2(28,30));lifeCounter=Label(h,life.Count+"  "+LifeTime(),new Vector2(12,21),21,bounds:new Vector2(112,40));}
  void PlayFromJourney(){life.Refresh(Now);if(life.Count==0){var p=Modal("No Lives",300);refillCountdown=Label(p,"Yeni can: "+LifeTime()+"\nCanlar 30 dakikada bir yenilenir.",new Vector2(0,132),22,bounds:new Vector2(330,100));Button(p,"Journey",new Vector2(0,235),new Vector2(245,60),colors[2],Journey);return;}journey=false;launchedFromJourney=true;BuildLevel();}
  bool journeyCompleted;
  void Journey(){
   if(!diagnosticsActive){PlayerPrefs.SetInt("visitedJourney",1);PlayerPrefs.Save();}
   StopAllCoroutines();if(overlay)Destroy(overlay.gameObject);if(suspendedShop)Destroy(suspendedShop.gameObject);suspendedShop=null;if(game)Destroy(game.gameObject);
   boxes.Clear();portals.Clear();stones.Clear();balls.Clear();trays.Clear();beltSockets.Clear();marblePool.Clear();marbleVisuals.Clear();sparkPool.Clear();activeBalls=0;
   journey=true;paused=true;won=false;overlay=null;game=ScreenPanel("Journey",new Color32(21,149,245,255));Picture(game,"journey-bg",new Vector2(0,H/2),new Vector2(W,H));
   ProfileButton(game,new Vector2(-190,107));LifeHud(game);
   var currency=Picture(game,"hud",new Vector2(142,107),new Vector2(154,43));Picture(currency,"coin",new Vector2(-57,21),new Vector2(27,29));coinText=Label(currency,journeyRewardPending?(coins-pendingReward).ToString("N0",System.Globalization.CultureInfo.InvariantCulture):FormatCoins(),new Vector2(-13,21),29,bounds:new Vector2(83,43));var add=Button(game,"",new Vector2(194,107),new Vector2(45,47),colors[0],Shop);Picture(add,"plus",new Vector2(0,22),new Vector2(31,31));
   var routeBack=Panel(game,"Golden route",new Vector2(0,300),new Vector2(14,480),new Color32(217,143,0,255));routeBack.SetSiblingIndex(1);var routeShine=Panel(game,"Route highlight",new Vector2(-2,300),new Vector2(5,480),colors[0]);routeShine.SetSiblingIndex(2);
   var route=BuildJourneyRoute();
   int[] milestones={41,61,71,91,131};for(int i=0;i<5;i++){int target=milestones[i];var marker=Button(game,"",new Vector2(-170,235+i*108),new Vector2(74,82),purple,()=>FeatureInfo(target));Picture(marker,"feature-"+i,new Vector2(0,32),new Vector2(63,63));Label(marker,"Lv. "+target,new Vector2(0,71),15,bounds:new Vector2(76,22));}
   var play=Button(game,"Play",new Vector2(0,745),new Vector2(235,90),colors[0],PlayFromJourney,43);var playLabel=play.Find("Button label") as RectTransform;if(playLabel){playLabel.anchorMin=playLabel.anchorMax=Vector2.one*.5f;playLabel.pivot=Vector2.one*.5f;playLabel.anchoredPosition=Vector2.zero;}var mask=play.gameObject.AddComponent<Mask>();mask.showMaskGraphic=true;var shine=Panel(play,"Play shine",new Vector2(-165,45),new Vector2(42,120),new Color(1,1,1,.16f));shine.localRotation=Quaternion.Euler(0,0,-18);var motion=play.gameObject.AddComponent<PlayButtonMotion>();motion.Bind(shine);JourneyTabs(game,1);ScaleScreenContents(game);if(journeyCompleted)StartCoroutine(journeyRewardPending?JourneyRewardSequence(route):AdvanceJourney(route));
  }
  void JourneyTabs(RectTransform parent,int selected){Panel(parent,"Navigation",new Vector2(0,944),new Vector2(450,80),new Color32(64,54,94,255));string[] icons={"nav-shop","nav-play","gear"};for(int i=0;i<3;i++){int tab=i;var button=Panel(parent,"Tab "+i,new Vector2(-150+i*150,938),new Vector2(140,78),i==selected?purple:Color.clear);var image=button.GetComponent<Image>();if(i==selected){image.sprite=Art("button-purple");image.type=Image.Type.Simple;}image.raycastTarget=true;button.gameObject.AddComponent<TouchSpring>();button.gameObject.AddComponent<Button>().onClick.AddListener(()=>{Sfx("click",.5f);if(tab==0)Shop();else if(tab==1)Journey();else Settings();});Picture(button,icons[i],new Vector2(0,39),new Vector2(55,55));}}
  void OutOfSpace(){if(spaceOffer){FailLevel();return;}spaceOffer=true;var p=Modal("Out of Space!",400);Picture(p,"gumball",new Vector2(0,133),new Vector2(100,110));Label(p,"Bekleyen bilyeleri topla,\noynamaya devam et.",new Vector2(0,243),23,bounds:new Vector2(330,90));Button(p,"Play On · 900",new Vector2(0,326),new Vector2(270,60),colors[2],()=>{if(coins<900){Label(p,"Yeterli altın yok",new Vector2(0,285),17);return;}coins-=900;PlayerPrefs.SetInt("coins",coins);PlayerPrefs.Save();coinText.text=FormatCoins();foreach(var b in balls)b.magnetic=true;lastMatchTime=clock;Close();StartCoroutine(CleanAnimation());},27);Button(p,"×",new Vector2(157,29),new Vector2(43,43),colors[1],FailLevel,30);}
  void FailLevel(){if(failed||diagnosticsActive)return;failed=true;won=true;life.Lose(Now);SaveLives();Sfx("fail",.65f);var p=Modal("Level "+level,430);Button(p,"×",new Vector2(157,30),new Vector2(42,43),colors[1],Journey,32);for(int i=0;i<5;i++){var h=Picture(p,"heart",new Vector2(-112+i*56,125),new Vector2(48,51));if(i>=life.Count)h.GetComponent<UnityEngine.UI.Image>().color=new Color(.28f,.23f,.35f,1);}Label(p,"Level Failed!",new Vector2(0,214),30);Label(p,life.Count+" can  ·  "+LifeTime(),new Vector2(0,265),23);Button(p,life.Count>0?"Try Again":"Journey",new Vector2(0,352),new Vector2(270,65),colors[2],()=>{if(life.Count>0){journey=false;BuildLevel();}else Journey();},30);}
  void ConfirmQuit(){if(journey){Close();return;}var p=Modal("Leave Level?",330);Label(p,"Bölümden çıkarsan bir can kaybedersin.",new Vector2(0,125),21,bounds:new Vector2(330,85));Button(p,"Continue",new Vector2(0,213),new Vector2(265,60),colors[2],Close,28);Button(p,"Quit",new Vector2(0,283),new Vector2(200,45),colors[1],()=>{if(!failed&&!won){life.Lose(Now);SaveLives();}Journey();},23);}
 }
}
